void fn0() {




  final graph = [
    [0, 1],
    [1, 2],
    [2, 0],
    [1, 3],
    [3, 4],
    [4, 3],
  ];

  final n = graph.length;
  final inDegree = List<int>.filled(n, 0);
  final queue = <int>[];
  final sorted = <int>[];

  for (var i = 0; i < n; i++) {
    for (final edge in graph[i]) {
      inDegree[edge]++;
    }
  }

  for (var v in List.generate(n, (i) => i)) {
    if (inDegree[v] == 0) {
      queue.add(v);
    }
  }

  while (queue.isNotEmpty) {
    final current = queue.removeFirst();
    sorted.add(current);

    for (final neighbor in graph[current]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
  }

  if (sorted.length == n) {
    print('Topological Sort: ${sorted.join(' -> ')}');
  } else {
    print('Graph contains a cycle, topological sort not possible.');
  }
}

