bool wordBreak(String s, List<String> wordDict) {
  if (s.isEmpty || wordDict.isEmpty) return false;
  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

int minWordBreak(String s, List<String> wordDict) {
  if (s.isEmpty || wordDict.isEmpty) return 0;
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, s.length + 1);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != s.length + 1 && wordSet.contains(s.substring(j, i))) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }
  return dp[s.length];
}

