  for (int i = 0; i <= s.length; i++) {
    final prefix = s.substring(0, i);
    if (wordDict.contains(prefix)) {
      final suffix = s.substring(i);
      if (wordBreakMinLength(suffix, wordDict) < minLength) {
        minLength = wordBreakMinLength(suffix, wordDict);
      }
    }
  }
  return minLength;
}

