int kPermutations(String items, int k) {
  if (k < 0 || k > items.length) return 0;
  if (k == 0) return 1;

  final remainingLength = items.length - k;
  final remaining = items.substring(0, remainingLength);
  final chosen = items.substring(remainingLength);

  return kPermutations(remaining, k - 1) * kPermutations(chosen, k - 1);
}

