int computeTotalCombinations(int k, List<String> items, bool repeat) {
  if (k <= 0) {
    return 1; 
  }
  if (items.isEmpty) {
    return 0; 
  }

  int n = items.length;
  int total = 0;

  for (int i = 0; i < k; i++) {
    final current = items[i];
    final remaining = items.sublist(0, i) + items.sublist(i + 1);
    final remainingCount = repeat ? n - (i + 1) : (n - i - 1);

    for (int j = 0; j < remainingCount; j++) {
      total += computeTotalCombinations(k - 1, remaining, repeat);
    }
  }

  return total;
}

