int _calculateTotalCombinations(int n, int k) {
  if (n <= 0 || k <= 0 || k > n) return 0;
  if (k == 1) return n;
  return _calculateTotalCombinations(n - 1, k - 1) * n;
}

void _generateCombinations(List<String> items, int k) {
  final n = items.length;
  if (n <= 0 || k <= 0 || k > n) return;
  if (k == 1) {
    print(items);
    return;
  }

  for (int i = 0; i < items.length; i++) {
    final remaining = <String>[];
    for (int j = 0; j < items.length; j++) {
      if (i != j) {
        remaining.add(items[j]);
      }
    }
    _generateCombinations(remaining, k - 1);
  }
}

