    stack.add(v);
    queue.add(v);

    while (stack.isNotEmpty) {
      int current = stack.removeLast();

      for (int neighbor in graph[current] ?? const []) {
        if (!visited.contains(neighbor)) {
          visited.add(neighbor);
          stack.add(neighbor);
          queue.add(neighbor);
