List<int> fn0(List<String> events) {
  List<int> openSeats = [];
  Set<String> occupied = {};
  Set<String> shared = {};
  bool cornerAllowed = false;

  for (String event in events) {
    if (event.isEmpty) {
      continue;
    }

    List<String> parts = event.split(' ');
    String seat = parts[0];
    String action = parts[1];

    if (action == '!') {
      if (seat.length != 2) {
        return [-1, -1];
      }

      int file = seat.codeUnitAt(0) - 96;
      int rank = int.parse(seat[1]);

      if (file < 0 || file > 7 || rank < 0 || rank > 7) {
        return [-1, -1];
      }

      String key = '${file}:${rank}';
      if (occupied.contains(key)) {
        return [-1, -1];
      }

      occupied.add(key);
      shared.remove(key);
      openSeats.add(file * 8 + rank);

      if (shared.isEmpty) {
        openSeats.sort();
      }
    } else if (action == '*') {
      if (seat.length != 2) {
        return [-1, -1];
      }

      int file = seat.codeUnitAt(0) - 96;
      int rank = int.parse(seat[1]);

      if (file < 0 || file > 7 || rank < 0 || rank > 7) {
        return [-1, -1];
      }

      String key = '${file}:${rank}';
      if (!occupied.contains(key)) {
        return [-1, -1];
      }

      occupied.remove(key);
      shared.add(key);
      openSeats.add(file * 8 + rank);
      if (openSeats.isEmpty) {
        openSeats.add(-1);
      }
    } else if (action == '^') {
      if (seat.length != 2) {
        return [-1, -1];
      }

      int file = seat.codeUnitAt(0) - 96;
      int rank = int.parse(seat[1]);

      if (file < 0 || file > 7 || rank < 0 || rank > 7) {
        return [-1, -1];
      }

      String key = '${file}:${rank}';
      if (shared.contains(key)) {
        shared.remove(key);
        openSeats.add(file * 8 + rank);
      }
    } else if (action == '#') {
      if (seat.length != 2) {
        return [-1, -1];
      }

      int file = seat.codeUnitAt(0) - 96;
      int rank = int.parse(seat[1]);

      if (file < 0 || file > 7 || rank < 0 || rank > 7) {
        return [-1, -1];
      }

      String key = '${file}:${rank}';
      if (cornerAllowed && shared.contains(key)) {
        shared.remove(key);
        openSeats.add(file * 8 + rank);
      }
    } else if (action == '?') {
      if (seat.length != 2) {
        return [-1, -1];
      }

      int file = seat.codeUnitAt(0) - 96;
      int rank = int.parse(seat[1]);

      if (file < 0 || file > 7 || rank < 0 || rank > 7) {
        return [-1, -1];
      }

      String key = '${file}:${rank}';
      if (shared.contains(key)) {
        shared.remove(key);
        openSeats.add(file * 8 + rank);
      }
    }
  }

  if (shared.isEmpty) {
    return [-1, -1];
  }

  int first = shared.firstKey.split(':')[0].codeUnitAt(0) - 96;
  int last = shared.lastKey.split(':')[0].codeUnitAt(0) - 96;

  if (first < 0 || first > 7 || last < 0 || last > 7) {
    return [-1, -1];
  }

  int bestFile = (first + last) ~/ 2;
  int bestRank = (first + rank > last + rank) ? first + rank : last + rank;

  return [bestFile, bestRank];
}

