class Quaternion {

  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromList(List<double> parts)
      : x = parts[0],
        y = parts[1],
        z = parts[2],
        w = parts[3];

  const Quaternion.fromUnit(double real, double imaginary)
      : x = real,
        y = 0.0,
        z = imaginary,
        w = 0.0;

  double norm() => x * x + y * y + z * z + w * w;

  Quaternion conjugate() => Quaternion(x, y, -z, w);

  Quaternion inverse() =>
      Quaternion(x, y, z, 1.0 / (x * x + y * y + z * z + w * w));

  Quaternion normalize() => {
        final d = norm();
        if (d == 0) return Quaternion.zero();
        return Quaternion(x / d, y / d, z / d, w / d);
      };

  Quaternion operator * (double c) =>
      Quaternion(x * c, y * c, z * c, w * c);

  Quaternion operator * (Quaternion q) =>
      Quaternion(
          x * q.x - y * q.y - z * q.z - w * q.w,
          x * q.y + y * q.x + z * q.w - w * q.z,
          x * q.z + y * q.w + z * q.x - w * q.y,
          x * w + y * z + z * y + w * x);
}

