  /// The result is a quaternion with w = 1 / (x^2 + y^2 + z^2) and x', y', z' = -x, -y, -z.
  Quaternion get inverse =>
      Quaternion(1 / (x * x + y * y + z * z), -x, -y, -z);

  /// Returns the conjugate of the quaternion.
  /// The conjugate is computed by changing the sign of the vector part.
  /// This operation normalizes the quaternion.
  /// The result is a quaternion with w = w and x', y', z' = x, y, z.
  Quaternion get conjugate => Quaternion(w, x, y, z);

  /// Returns the norm of the quaternion.
  /// The norm is computed by the Euclidean norm of the vector part.
  /// A quaternion with w = 0 has norm 0.
  double get norm =>
      (x * x + y * y + z * z) * 0.5 + w * 0.5;

  /// Returns the normalized form of the quaternion.
  /// The normalized form has w = 1 / (x^2 + y^2 + z^2) and x', y', z' = x, y, z.
  /// A quaternion with w = 0 is normalized to the origin.
  Quaternion get normalized =>
      norm == 0 ? Quaternion(0.0, 0.0, 0.0) : this / norm;

  /// Returns the conjugate of the conjugate of the quaternion.
  /// This is equivalent to the original quaternion.
  Quaternion get hermitian => conjugate * conjugate;

  /// Returns the conjugate of the conjugate of the conjugate of the quaternion.
  /// This is equivalent to the original quaternion.
  Quaternion get unit => hermitian * hermitian;

  /// Returns the dot product of two quaternions.
  /// The dot product is computed by multiplying the corresponding vector parts.
  /// A quaternion with w = 0 has dot product 0 with any other quaternion.
  double dot(Quaternion other) =>
