class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double x1 = x, y1 = y, z1 = z, w1 = w;
    double x2 = other.x, y2 = other.y, z2 = other.z, w2 = other.w;

    double e0 = x1 * x2 - y1 * y2 - z1 * z2 - w1 * w2;
    double e1 = x1 * y2 + y1 * x2 + z1 * w2 - w1 * z2;
    double e2 = x1 * z2 - y1 * w2 + z1 * x2;
    double e3 = x1 * w2 + y1 * z2 - w1 * x2;

    return Quaternion(e0, e1, e2, e3);
  }

  double norm() {
    double sum = x * x + y * y + z * z + w * w;
    return sum.sqrt();
  }

  Quaternion normalized() {
    return Quaternion((x / norm()), (y / norm()), (z / norm()), (w / norm()));
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion((x / n) - (y * z + w * w) / (n * n),
                    (y / n) - (x * z + w * w) / (n * n),
                    (z / n) - (x * w + y * x) / (n * n),
                    (w / n) - (x * y + z * x) / (n * n));
  }

  Quaternion rotateZ(double theta) {
    double sinT = theta.abs() < 0.00001 ? 0.0 : theta.sin();
    double cosT = theta.abs() < 0.00001 ? 1.0 : theta.cos();
    double sx = x * x * (1 - cosT), sy = y * y * (1 - cosT), sz = z * z * (1 - cosT);
    double syx = x * y * (cosT), syz = z * y * (cosT), sxz = x * z * (cosT);
    double sinX = x * sinT, sinY = y * sinT, sinZ = z * sinT;

    return Quaternion(sx, sy, sz, sinX + syx + sxz);
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

