class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.fromList(List<double> list)
      : x = list[0], y = list[1], z = list[2], w = list[3];

  const Quaternion.fromTuple(Tuple4<double> t)
      : x = t.x, y = t.y, z = t.z, w = t.w;

  const Quaternion.fromComplex(Complex c)
      : x = c.real, y = c.imag, z = -c.imag, w = c.real;

  const Quaternion.fromEuler(double e1, double e2, double e3)
      : x = 0.0,
        y = -e3,
        z = 0.0,
        w = (e1 * e1 + e2 * e2) * 0.5;

  const Quaternion.fromAxisAngle(
    Vector3 axis,
    double angle,
  ) : x = 0.0,
        y = 0.0,
        z = 0.0,
        w = (axis.x * axis.x + axis.y * axis.y + axis.z * axis.z) * 0.5;

  const Quaternion.fromRodrigues(
    Vector3 x,
    Vector3 y,
    Vector3 z,
  ) : x = 2 * (x.x + y.y + z.z),
        y = 2 * (y.x + z.y),
        z = 2 * (z.x + x.z),
        w = 1.0 - 2 * (x.x * x.x + y.y * y.y + z.z * z.z);

  const Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(Quaternion other) =>
      Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * z - y * w + z * other.x + w * other.y,
        x * w + y * z - z * y + w * x,
      );

  const Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator /(Quaternion other) {
    final inv = other.w * other.w - other.x * other.x - other.y * other.y - other.z * other.z;
    if (inv == 0.0) throw ArgumentError('Division by zero quaternion');
    return Quaternion(
      (x * other.x + y * other.y + z * other.z) / inv,
      (x * other.y - y * other.x + z * other.w) / inv,
      (x * z + y * w) / inv,
      (y * z - x * w) / inv,
    );
  }

  const Quaternion operator ^(Quaternion other) {
    final half = other * 0.5;
    return Quaternion(
      (1.0 - half.x * half.x - half.y * half.y - half.z * half.z) * 0.5,
      (half.x * other.x - half.y * other.y) + (half.z * other.w),
      (half.y * other.x + half.z * other.y),
      (half.x * other.z - half.y * other.w),
    );
  }

  const Quaternion conjugate() => Quaternion(x, -y, -z, w);

  const Quaternion inverse() {
    final inv = w * w - x * x - y * y - z * z;
    if (inv == 0.0) throw ArgumentError('Inverse of zero quaternion');
    return Quaternion(
      (x * x + y * y + z * z) / inv,
      (-x * y + z * w) / inv,
      (-y * z + x * w) / inv,
      (x * w - y * z) / inv,
    );
  }

  const Quaternion normalized() {
    final norm = x * x + y * y + z * z + w * w;
    if (norm == 0.0) return Quaternion.zero();
    return Quaternion((x * x + y * y + z * z) / norm, (2 * x * w + 2 * y * z) / norm, (2 * z * x - 2 * y * w) / norm, (2 * w * y - 2 * x * z) / norm);
  }

  const Quaternion norm() => (x * x + y * y + z * z + w * w) * 0.5;

  const Quaternion rotate(Vector3 axis, double angle) {
    final axis2 = axis * 2.0;
    final sinAng = sin(angle);
    final cosAng = cos(angle);
    return Quaternion(
      cosAng * (1.0 - axis2.dot(axis2)),
      sinAng * axis2.x + cosAng * axis.x,
      sinAng * axis2.y + cosAng * axis.y,
      sinAng * axis2.z + cosAng * axis.z,
    );
  }

  const Quaternion rotate(Vector3 axis, double angle, [bool conjugate = false]) {
    if (axis.length != 3) throw ArgumentError('Invalid axis');
    if (angle < 0.0) throw ArgumentError('Invalid angle');
    if (conjugate) {
      final axis2 = axis * 2.0;
      final sinAng = sin(angle);
      final cosAng = cos(angle);
      return Quaternion(
        cosAng * (1.0 - axis2.dot(axis2)),
        -sinAng * axis2.x + cosAng * axis.x,
        -sinAng * axis2.y + cosAng * axis.y,
        -sinAng * axis2.z + cosAng * axis.z,
      );
    }
    final sinAng = sin(angle);
    final cosAng = cos(angle);
    return Quaternion(
      cosAng * (1.0 - axis2.dot(axis2)),
      sinAng * axis2.x + cosAng * axis.x,
      sinAng * axis2.y + cosAng * axis.y,
      sinAng * axis2.z + cosAng * axis.z,
    );
  }
}

