class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  /// Quaternion with all components normalized to 1.
  /// Uses the standard Gram-Schmidt orthonormalization algorithm.
  /// Parallel axes are rotated by 90° about the perpendicular axis.
  /// Returns a Quaternion whose norm is 1.
  static Quaternion normalize(Quaternion q) {
    final len = q.w * q.w + q.x * q.x + q.y * q.y + q.z * q.z;
    if (len == 0) {
      return const Quaternion(0, 0, 0, 0);
    }
    final norm = 1 / len;
    return Quaternion(q.x * norm, q.y * norm, q.z * norm, q.w * norm);
  }

  /// Quaternion whose norm is 1, parallel axes are rotated by 90° about the
  /// perpendicular axis, and the z-axis is the axis of rotation.
  static Quaternion orthonormalize(Quaternion q) {
    final len = q.w * q.w + q.x * q.x + q.y * q.y + q.z * q.z;
    if (len == 0) {
      return const Quaternion(0, 0, 0, 0);
    }
    final norm = 1 / len;
    final xx = q.x * q.x;
    final yy = q.y * q.y;
    final zz = q.z * q.z;
    final w = q.w * norm;
    return Quaternion(
      (3 - 2 * xx - 2 * yy - 2 * zz) * w,
      (2 - 2 * xx - 2 * zz) * w,
      (2 - 2 * yy - 2 * zz) * w,
      -4 * w,
    );
  }

  /// Quaternion conjugate: x -> x, y -> -y, z -> -z, w -> w.
  static Quaternion conjugate(Quaternion q) =>
      Quaternion(q.x, -q.y, -q.z, q.w);

  /// Quaternion addition: (x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2, (w1 + w2) / 2.
  static Quaternion operator +(Quaternion q1, Quaternion q2) =>
      Quaternion(
        (q1.x + q2.x) / 2,
        (q1.y + q2.y) / 2,
        (q1.z + q2.z) / 2,
        (q1.w + q2.w) / 2,
      );

  /// Quaternion subtraction: (x1 - x2) / 2, (y1 - y2) / 2, (z1 - z2) / 2, (w1 - w2) / 2.
  static Quaternion operator -(Quaternion q1, Quaternion q2) =>
      Quaternion(
        (q1.x - q2.x) / 2,
        (q1.y - q2.y) / 2,
        (q1.z - q2.z) / 2,
        (q1.w - q2.w) / 2,
      );

  /// Quaternion multiplication: (x1 * x2 - y1 * y2 - z1 * z2 + w1 * w2) / 2,
  /// (y1 * x2 + x1 * y2) / 2, (z1 * x2 + y1 * z2) / 2,
  /// (w1 * x2 + y1 * w2) / 2.
  static Quaternion operator *(Quaternion q1, Quaternion q2) =>
      Quaternion(
        (q1.x * q2.x - q1.y * q2.y - q1.z * q2.z + q1.w * q2.w) / 2,
        (q1.y * q2.x + q1.x * q2.y),
        (q1.z * q2.x + q1.y * q2.z),
        (q1.w * q2.x + q1.y * q2.w),
      );

  /// Quaternion negation: (-x, -y, -z, -w).
  static Quaternion operator -(Quaternion q) =>
      Quaternion(-q.x, -q.y, -q.z, -q.w);

  /// Quaternion multiplication by a scalar: (x * scalar, y * scalar, z * scalar, w * scalar).
  static Quaternion operator *(Quaternion q, double scalar) =>
      Quaternion(q.x * scalar, q.y * scalar, q.z * scalar, q.w * scalar);

  /// Quaternion inverse: (x / (x^2 + y^2 + z^2 + w^2), y / (x^2 + y^2 + z^2 + w^2),
  /// z / (x^2 + y^2 + z^2 + w^2), w / (x^2 + y^2 + z^2 + w^2)).
  static Quaternion operator /(Quaternion q) {
    if (q.w == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    final denom = q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w;
    return Quaternion(
      q.x / denom,
      q.y / denom,
      q.z / denom,
      q.w / denom,
    );
  }

  /// Quaternion magnitude (norm): sqrt(x^2 + y^2 + z^2 + w^2).
  double norm() => sqrt(x * x + y * y + z * z + w * w);

  /// Quaternion square: (x^2 - y^2 - z^2 + w^2) / 2, 2 * x * y, 2 * x * z, 2 * x * w.
  Quaternion square() =>
      Quaternion((x * x - y * y - z * z + w * w) / 2, 2 * x * y, 2 * x * z, 2 * x * w);

  /// Quaternion * 2: (2 * x, 2 * y, 2 * z, w).
  Quaternion operator *(2) => Quaternion(2 * x, 2 * y, 2 * z, w);

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

