          int ni = i + d[0];
          int nj = j + d[1];
          if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && moistureGrid[ni][nj] <= threshold) {
            dp[i][j] += dp[ni][nj];
          }
        }
      }
    }
  }
  Map<String, int> result = {};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (dp[i][j] >= 2) {
        result["$i,$j"] = 1;
      }
    }
  }
  return result;
}

