Map<String, int> fn0(List<int> weights, int capacity) {
  if (weights.isEmpty) return {};
  List<List<int>> dp = List.generate(weights.length + 1, (_) => List.filled(capacity + 1, -1));
  dp[0][0] = 0;
  for (int i = 1; i <= weights.length; i++) {
    for (int w in weights) {
      if (w <= 0) continue;
      for (int j = 0; j <= capacity; j++) {
        if (dp[i - 1][j] == -1) continue;
        int currW = dp[i - 1][j] + w;
        int currCap = dp[i - 1][j] < j ? dp[i - 1][j] : j;
        dp[i][currCap] = currW >= 0 ? currW : -1;
        if (currCap > 0) {
          dp[i][currCap - 1] = currW >= 0 ? currW : -1;
        }
      }
    }
  }
  Map<String, int> result = {};
  for (int i = 0; i <= weights.length; i++) {
    for (int j = 0; j <= capacity; j++) {
      if (dp[i][j] == -1) continue;
      if (dp[i][j] >= 0) {
        result[i.toString() + '-' + j.toString()] = dp[i][j];
      }
    }
  }
  return result;
}

