Map<String, int> fn0(List<int> rounds, int targetSum) {
  if (rounds.isEmpty) return {};
  int n = rounds.length;
  if (n == 1) return {rounds[0].toString(): rounds[0]};
  List<int> prefix = List<int>.filled(n, 0);
  for (int i = 0; i < n; i++) {
    prefix[i] = rounds[i] + (i == 0 ? 0 : prefix[i - 1]);
  }
  int low = 0;
  int high = n - 1;
  while (low <= high) {
    int mid = low + ((high - low) >> 1);
    if (prefix[mid] < targetSum) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  int left = low;
  int right = n - 1;
  while (left < right) {
    int mid = left + ((right - left) >> 1);
    if (prefix[mid] > targetSum) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  Map<String, int> result = {};
  if (left > 0) {
    result["${rounds[left - 1]}-${rounds[left]}"] = rounds[left - 1] + rounds[left];
  }
  if (right < n - 1) {
    result["${rounds[right]}-${rounds[right + 1]}"] = rounds[right] + rounds[right + 1];
  }
  return result;
}

