    List<int> lps = List.filled(n, 0);
    int len = 0;
    int i = 1;

    while (i < n) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return n;
  }

  int computeKMP(String pattern) {
    int len = computeLPSArray(pattern);
    int i = 0;
    int j = 0;

    while (i < text.length) {
      if (pattern[j] == text[i]) {
        i++;
        j++;
      }
      if (j == patternLength) {

        return i - j;
      }
      if (i < text.length && pattern[j] != text[i]) {
        if (j != 0) {
          j = lps[j - 1];
        } else {
          i++;
        }
      }
    }
    return -1;
