void computeLPSArray(String pattern, int patternLength, List<List<int>> lps) {
  int len = 0; 
  int i = 1;

  while (i < patternLength) {
    if (pattern[len] == pattern[i]) {
      len++;
      i++;
    }
    if (i == patternLength) {
      lps[len][0] = len;
      len = lps[len - 1][len - 1];
    } else if (pattern[len] != pattern[i]) {
      if (len != 0) {
        len = lps[len - 1][len];
      } else {
        i++;
      }
    }
  }
}

void printLPSArray(List<List<int>> lps) {
  int n = lps.length;
  for (int i = 0; i < n; i++) {
    print('  At index $i: ${lps[i]}');
  }
}

