int fn0(List<int> seeds, int challengeSeed) {
  int n = seeds.length;
  if (n == 0) return 0;

  List<int> dp = List<int>.filled(n + 1, 0);

  for (int i = 0; i < n; i++) {
    int base = seeds[i];
    if (base < 0) {
      base = 0;
    }
    for (int j = i - 1; j >= 0; j--) {
      int prev = seeds[j];
      if (prev < 0) {
        prev = 0;
      }
      int gain = base - prev;
      if (gain > 0) {
        dp[i] = dp[i] > dp[j] + gain ? dp[i] : dp[j] + gain;
      }
    }
  }

  int result = dp[n];
  return (result < 0 ? 0 : result) + challengeSeed;
}

