import 'dart:async';
import 'dart:convert';
class Role {
  String name;
  List<String> permissions;
  Role? parent;
  Map<String, Role> children = {};

  Role(this.name, this.permissions, [this.parent]);

  void addChild(String name, Role role) {
    role.parent = this;
    children[name] = role;
  }
}

class Resource {
  String name;
  List<String> permissions = [];

  Resource(this.name);
}

class User {
  String username;
  List<String> roles = [];
  Map<String, Resource> resources = {};

  User(this.username);

  void addRole(String roleName) {
    if (!roles.contains(roleName)) {
      roles.add(roleName);
    }
  }

  void addResource(String resourceName, Resource resource) {
    resources[resourceName] = resource;
  }
}

class AccessControlSystem {
  Map<String, Role> roles = {};
  Map<String, Resource> resources = {};
  Map<String, User> users = {};

  void grantPermissions(String user, String resource, List<String> permissions) {
    if (!resources.containsKey(resource)) {
      print('Resource "$resource" not found.');
      return;
    }

    if (!users.containsKey(user)) {
      print('User "$user" not found.');
      return;
    }

    List<String> existingPermissions = resources[resource]!.permissions;

    for (var permission in permissions) {
      if (!existingPermissions.contains(permission)) {
        print('Action "$permission" denied for "$user" on "$resource".');
        return;
      }
    }

    for (var role in users[user]!.roles) {
      var roleDetails = roles[role]!;
      if (roleDetails.permissions.containsAll(permissions)) {
        print('  ➜ Access GRANTED (Role: "${roleDetails.name}")');
        return;
      }
    }

    print('  ➜ Access DENIED (Insufficient permissions)');
  }

  void denyPermissions(String user, String resource) {
    if (!resources.containsKey(resource)) {
      print('Resource "$resource" not found.');
      return;
    }

    if (!users.containsKey(user)) {
      print('User "$user" not found.');
      return;
    }

    List<String> existingPermissions = resources[resource]!.permissions;

    for (var role in users[user]!.roles) {
      var roleDetails = roles[role]!;
      if (!roleDetails.permissions.containsAll(existingPermissions)) {
        print('  ➜ Access denied\n');
        return;
      }
    }

    print('  ➜ Access granted\n');
  }

  void displayRole(Role role) {
    print('Role: ${role.name}');
    print('Permissions: ${role.permissions.join(', ')}');
    if (role.parent != null) {
      print('Parent: ${role.parent!.name}');
    }
    print('');
  }

  void displayResource(Resource resource) {
    print('Resource: ${resource.name}');
    print('Permissions: ${resource.permissions.join(', ')}\n');
  }

  void displayUser(User user) {
    print('User: ${user.username}');
    print('Roles: ${user.roles.join(', ')}\n');
  }

  void displayAccessMatrix() {
    print('User/Resource Access Matrix:\n');
    String formatCell(String user, String resource, String status) {
      return '<span style="color: ${status == "GRANTED" ? "green" : "red"}">${user}/${resource}</span>';
    }

    for (var user in resources.keys) {
      String userLabel = user.padLeft(6);
      print(userLabel + ': ');

      for (var resource in resources.keys) {
        var grantStatus = grantPermissions(user, resource, resources[resource]!.permissions);
        var denyStatus = denyPermissions(user, resource);

        print(formatCell(user, resource, grantStatus ? 'GRANTED' : denyStatus ? 'DENIED' : 'UNKNOWN'));
      }
    }
  }

  void displayAuditLog() {
    print('--- Audit Log ---\n');

    for (var user in resources.keys) {
      print('User "${user}" attempts to:');
      for (var resource in resources.keys) {
        if (grantPermissions(user, resource, resources[resource]!.permissions)) {
          print('  ➜ ${resources[resource]!.name}');
        } else {
          print('  ➜ ${resources[resource]!.name}');
        }
      }
      print('');
    }
  }

  void displayRecentAccessAttempts() {
    print('Recent Access Attempts:');
    for (var user in resources.keys) {
      print('  ➜ User "${user}" attempts to:');
      for (var resource in resources.keys) {
        if (grantPermissions(user, resource, resources[resource]!.permissions)) {
          print('  ➜ ${resources[resource]!.name}');
        } else {
          print('  ➜ ${resources[resource]!.name}');
        }
      }
      print('');
    }
  }

  void displayPermissionsOverview() {
    print('--- User Permissions Overview ---\n');
    for (var user in resources.keys) {
      print('User "${user}": ${resources[user]!.roles.join(', ')}');
    }
  }

  void displayResourceMatrix() {
    print('--- Resource Access Matrix ---\n');
    for (var resource in resources.keys) {
      displayResource(resource);
    }
  }

  void displayRolesOverview() {
    print('--- Role Hierarchy:');
    roles.forEach(displayRole);
  }

  void displaySystemSummary() {
    print('\n=== System Summary ===');
    print('Total Users: ${users.length}');
    print('Total Resources: ${resources.length}');
    print('Total Roles: ${roles.length}');
    displayPermissionsOverview();
    displayResourceMatrix();
    displayRolesOverview();
    displayAuditLog();
    displayRecentAccessAttempts();
  }

  void run() {

    var adminRole = Role('admin', ['read', 'write', 'delete', 'admin']);
    var moderatorRole = Role('moderator', ['read', 'write', 'delete'], adminRole);
    var editorRole = Role('editor', ['read', 'write'], adminRole);
    var viewerRole = Role('viewer', ['read'], adminRole);

    var sensitiveDataResource = Resource('sensitive_data');
    sensitiveDataResource.permissions.add('read');
    sensitiveDataResource.permissions.add('write');
    sensitiveDataResource.permissions.add('delete');

    var document1 = Resource('document1');
    document1.permissions.add('read');

    var document2 = Resource('document2');
    document2.permissions.add('write');
    document2.permissions.add('edit');

    var userAlice = User('alice');
    userAlice.addRole(adminRole.name);
    userAlice.addRole(moderatorRole.name);
    userAlice.addResource('sensitive_data', sensitiveDataResource);
    userAlice.addResource('document1', document1);

    var userBob = User('bob');
    userBob.addRole(editorRole.name);
    userBob.addResource('document2', document2);

    var userCharlie = User('charlie');
    userCharlie.addRole(viewerRole.name);

    roles.add(adminRole);
    roles.add(moderatorRole);
    roles.add(editorRole);
    roles.add(viewerRole);

    resources.add('sensitive_data', sensitiveDataResource);
    resources.add('document1', document1);
    resources.add('document2', document2);

    users.add(userAlice.username, userAlice);
    users.add(userBob.username, userBob);
    users.add(userCharlie.username, userCharlie);

    grantPermissions(userAlice.username, 'sensitive_data', ['read', 'write', 'delete']);
    grantPermissions(userBob.username, 'document2', ['read', 'write', 'edit']);
    grantPermissions(userCharlie.username, 'document1', ['read']);

    print('=== Role-Based Access Control System ===\n');

    displayAccessMatrix();

    grantPermissions(userBob.username, 'sensitive_data', ['read']);
    print('Attempting to access admin resource...');

    denyPermissions(userAlice.username, 'document1');
    print('Attempting to access admin resource again...');

    displayRolesOverview();

    displayRecentAccessAttempts();

    var newUser = User('diana');
    newUser.addRole(editorRole.name);
    newUser.addResource('document2', document2);
    grantPermissions(newUser.username, 'document2', ['read', 'write', 'edit']);

    print('\n--- Permission Inheritance Demo ---\n');
    var parentRole = newUser.roles[0];
    print('Current role for "${newUser.username}": ${parentRole.name}');
    print('Permissions: ${parentRole.permissions.join(', ')}');

    var nestedRole = Resource('resource_1').permissions;
    var nestedChild = nestedRole[0];
    print('Action "${nestedChild}" not found');

    print('\n--- Access Control Tests ---\n');
    grantPermissions(userAlice.username, 'sensitive_data', ['read', 'write', 'delete']);
    grantPermissions(userBob.username, 'document2', ['read', 'write', 'edit']);
    grantPermissions(userCharlie.username, 'document1', ['read']);

    grantPermissions(userBob.username, 'sensitive_data', ['read']);
    print('  ➜ Access granted\n');

    denyPermissions(userAlice.username, 'document1');
    print('  ➜ Access denied\n');

    denyPermissions(userBob.username, 'document2');
    print('  ➜ Access denied\n');

    print('--- Resource Access Matrix ---\n');
    displayResourceMatrix();

    print('--- Audit Log ---\n');
    displayAuditLog();

    print('=== System Summary ===');
    print('Total Users: ${users.length}');
    print('Total Resources: ${resources.length}');
    print('Total Roles: ${roles.length}');
    displayPermissionsOverview();
    displayResourceMatrix();
    displayRolesOverview();
    displayAuditLog();
  }
}

