import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;

  Role(this.name, [this.permissions = const []]);
}

class Permission {
  final String resource;
  final String action;

  Permission(this.resource, this.action);
}

class User {
  final String name;
  final Map<String, Role> roles = {};

  User(this.name);
}

class Resource {
  final String name;

  Resource(this.name);
}

class AccessControl {
  final Map<String, User> users = {};
  final Map<String, Resource> resources = {};
  final Set<String> actions = {'CREATE', 'READ', 'UPDATE', 'DELETE', 'VIEW'};

  bool denyAccess(String user, String resource, String action) {
    if (!actions.contains(action)) {
      print('  ❌ Unknown action: $action');
      return false;
    }
    if (!users.containsKey(user)) {
      print('  ❌ User "$user" not found');
      return false;
    }
    if (!resources.containsKey(resource)) {
      print('  ❌ Resource "$resource" not found');
      return false;
    }
    if (!users[user]!.hasPermission(resource, action)) {
      print('  ❌ Access denied (${users[user]!.currentRole})');
      return true;
    }
    print('  ✅ Access granted');
    return false;
  }

  void logAccess(String user, String resource, String action, bool granted) {
    String role = granted ? users[user]!.currentRole : 'DENIED';
    print(
        '[$action] ${granted ? '✅ SUCCESS' : '❌ DENIED'} | Role: $role | User: $user | Resource: $resource | Timestamp: ${DateTime.now()}');
  }

  bool userHasPermission(String user, String resource, String action) {
    if (!actions.contains(action)) {
      return false;
    }
    if (!users.containsKey(user)) {
      return false;
    }
    if (!resources.containsKey(resource)) {
      return false;
    }
    return users[user]!.hasPermission(resource, action);
  }

  bool resourceIsPublic(String resource) {
    return resource == 'document1' || resource == 'document2';
  }

  bool elevateRole(String user, String newRole) {
    if (!users.containsKey(user)) {
      print('  ❌ User "$user" not found');
      return false;
    }
    if (users[user]!.currentRole == newRole) {
      print('  ❌ Current role is already $newRole');
      return false;
    }
    Role newRoleObj = Role(newRole);
    users[user]!.roles.remove(newRoleObj);
    users[user]!.roles.add(newRoleObj);
    print('  ✅ Elevated "$user" to $newRole');
    return true;
  }

  bool transferPermission(String fromUser, String toUser, String resource, String action) {
    if (!actions.contains(action)) {
      return false;
    }
    if (!users.containsKey(fromUser)) {
      return false;
    }
    if (!users.containsKey(toUser)) {
      return false;
    }
    if (!resources.containsKey(resource)) {
      return false;
    }
    bool fromHas = users[fromUser]!.hasPermission(resource, action);
    bool toHas = users[toUser]!.hasPermission(resource, action);
    if (fromHas && !toHas) {
      users[toUser]!.roles.add(users[fromUser]!.currentRole);
      print('  ✅ Granted "${toUser}'s permission to "$resource"');
      return true;
    }
    return false;
  }

  void grantAllPermissions(String user, String resource) {
    if (!resources.containsKey(resource)) {
      return;
    }
    actions.forEach((action) {
      if (!userHasPermission(user, resource, action)) {
        users[user]!.roles.add(Role(action));
      }
    });
  }

  void revokeAllPermissions(String user, String resource) {
    if (!resources.containsKey(resource)) {
      return;
    }
    actions.forEach((action) {
      if (userHasPermission(user, resource, action)) {
        users[user]!.roles.remove(Role(action));
      }
    });
  }
}

