    List<int> result = [];
    for (int i = 0; i < 4; i++) {
      result.add((value >> (i * 8)) & 0xFF);
    }
    return result;
  }

  int fromBytes(List<int> bytes) {
    int result = 0;
    for (int i = 0; i < 4; i++) {
      result = (result << 8) | bytes[i];
    }
    return result;
  }

