  ];

  final minSupport = 0.5; 
  final minConfidence = 0.7; 

  final frequentItems = <List<String>>[];
  final frequentItemsets = <List<String>>[];
  final frequentItemsetKeys = <List<String>>[];


  final frequentItemsetSupport = <List<String>, double>{};
  final frequentItemsetConfidence = <List<String>, double>{};


  final allItems = Set<String>.from(transactions.expand((item) => item).toList());
  final allSubsets = <List<String>>[[]];

  while (true) {
    final currentFrequent = <List<String>>[];

    for (final subset in allSubsets) {
      final subsetItems = subset.toSet();
      final complement = allItems.difference(subsetItems);
      final support = complement.length / transactions.length;
      if (support >= minSupport) {
        currentFrequent.add(subset.toList());
      }
    }

    if (currentFrequent.isEmpty) {
      break;
    }

    for (final item in currentFrequent) {
      if (item.length > 1) {
        final itemset = item.toSet();

        final candidates = <List<String>>[];
        for (final current in itemset) {
          for (final subset in allSubsets) {
            if (subset.isEmpty || subset.length == current.length) {
              continue;
            }
            if (subset.length == current.length - 1) {
              final newCandidate = List.from(current) + subset;
              candidates.add(newCandidate);
            }
          }
        }

        for (final candidate in candidates) {
          if (candidate.length > 1) {

            final candidateSupport = candidate.toSet().length / transactions.length;
            if (candidateSupport >= minSupport) {
              frequentItems.add(candidate);
              frequentItemsets.add(candidate);

              if (frequentItemsetSupport.containsKey(candidate)) {
                frequentItemsetSupport[candidate] = (frequentItemsetSupport[candidate]! + candidateSupport) / 2;
              } else {
                frequentItemsetSupport[candidate] = candidateSupport;
              }

              if (frequentItemsetConfidence.containsKey(candidate)) {
                frequentItemsetConfidence[candidate] = (frequentItemsetConfidence[candidate]! + candidateSupport) / 2;
              } else {
                frequentItemsetConfidence[candidate] = candidateSupport;
              }

              frequentItemsetKeys.add(candidate);
            }
          }
        }
      }
    }

    allSubsets.addAll(currentFrequent);
  }

  frequentItemsets.sort((a, b) {
    final supportCompare = frequentItemsetSupport[b]!.compareTo(frequentItemsetSupport[a]!);
    if (supportCompare != 0) {
      return supportCompare;
    }

    final confidenceCompare = frequentItemsetConfidence[a]!.compareTo(frequentItemsetConfidence[b]!);
    if (confidenceCompare != 0) {
      return confidenceCompare;
    }

    if (a.length != b.length) {
      return a.length.compareTo(b.length);
    }

    return a.join(',').compareTo(b.join(','));
  });

  print('Frequent Itemsets:');
  for (final itemset in frequentItemsets) {
