      } else if (gap > 100) {
        totalDeficit += gap - 100;
      }
    }
    intervals.add(baseCents[i]);
  }
  List<int> distinct = [];
  int maxLen = 0;
  for (int v in intervals) {
    if (distinct.isEmpty || distinct.last != v) {
      distinct.add(v);
      if (distinct.length > maxLen) maxLen = distinct.length;
    }
  }
  return {'longestInterval': maxLen, 'totalDeficitDays': totalDeficit, 'distinctIntervals': distinct.length};
