Map<String, int> fn0(List<int> visitDays, int interval) {
  if (interval <= 0) {
    return {
      'longestInterval': 0,
      'totalDeficitDays': 0,
      'distinctIntervals': 0,
    };
  }

  final int n = visitDays.length;
  if (n == 0) return {};

  final List<int> intervals = [];
  int i = 0;
  while (i < n) {
    final int start = visitDays[i];
    while (i + interval <= n &&
        visitDays[i + interval] - start <= interval) {
      i += interval;
    }
    if (i >= n) break;
    final int end = visitDays[i];
    intervals.add(end - start);
    i += interval;
  }

  int longest = 0;
  int totalDeficit = 0;
  int distinctCount = 0;

  for (final int day in intervals) {
    if (longest < day) longest = day;
    totalDeficit += longest - day;
    if (longest == day) distinctCount++;
  }

  return {
    'longestInterval': longest,
    'totalDeficitDays': totalDeficit,
    'distinctIntervals': distinctCount,
  };
}

