class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
      {required this.x,
      required this.y,
      required this.width,
      required this.height});

  Rectangle.square(double side)
      : this(x: side, y: side, width: side, height: side);

  Rectangle.fromPoints(Point a, Point b)
      : this(x: a.x, y: a.y, width: b.x - a.x, height: b.y - a.y);

  Rectangle.fromCenter(
      double centerX, double centerY, double halfWidth, double halfHeight)
      : this(
          x: centerX - halfWidth,
          y: centerY - halfHeight,
          width: halfWidth * 2,
          height: halfHeight * 2,
        );

  bool contains(Point p) => x <= p.x && p.x <= x + width && y <= p.y && p.y <= y + height;

  bool contains(Rectangle rect) => contains(rect.x, rect.y) && contains(rect.x + rect.width, rect.y + rect.height);

  bool intersects(Rectangle rect) =>
      !contains(rect) && rect.contains(this);

  Rectangle union(Rectangle other) =>
      Rectangle.fromCenter(
        x: x < other.x ? x : other.x,
        y: y < other.y ? y : other.y,
        halfWidth: (width < other.width ? width : other.width) / 2,
        halfHeight: (height < other.height ? height : other.height) / 2,
      );

  Rectangle intersection(Rectangle other) =>
      Rectangle.fromCenter(
        x: x > other.x ? x : other.x,
        y: y > other.y ? y : other.y,
        halfWidth: (width > other.width ? width : other.width) / 2,
        halfHeight: (height > other.height ? height : other.height) / 2,
      );
}

