class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
    this.x,
    this.y,
    this.width,
    this.height,
  );

  Rectangle.fromPoints(Point p1, Point p2)
      : x = p1.x < p2.x ? p1.x : p2.x,
        y = p1.y < p2.y ? p1.y : p2.y,
        width = (p1.x - p2.x).abs(),
        height = (p1.y - p2.y).abs();

  Rectangle.square(double side) : this(0, 0, side, side);

  Rectangle.fromCircle(Point center, double radius)
      : x = center.x - radius,
        y = center.y - radius,
        width = 2 * radius,
        height = 2 * radius;

  Rectangle.fromRect(Rectangle rect) : this(rect.x, rect.y, rect.width, rect.height);

  Rectangle.withHalfDimensions(double halfWidth, double halfHeight)
      : this(0, 0, 2 * halfWidth, 2 * halfHeight);

  Rectangle.centered(Point center, double halfWidth, double halfHeight)
      : x = center.x - halfWidth,
        y = center.y - halfHeight,
        width = 2 * halfWidth,
        height = 2 * halfHeight;

  Rectangle.fromList(List<Point> points)
      : x = points[0].x < points[1].x ? points[0].x : points[1].x,
        y = points[0].y < points[1].y ? points[0].y : points[1].y,
        width = (points[0].x - points[1].x).abs(),
        height = (points[0].y - points[1].y).abs();

  bool contains(Point point) =>
      point.x >= x && point.x < x + width &&
      point.y >= y && point.y < y + height;

  bool intersects(Rectangle other) =>
      !((other.x - x).abs() > width + other.width ||
          (other.y - y).abs() > height + other.height));

  bool isZero() => width <= 0 && height <= 0;

  Rectangle union(Rectangle other) =>
      other.isZero() ? this : other.isZero() ? this :
          Rectangle.centered(
              Point((x < other.x ? x : other.x) - other.width / 2),
              other.width / 2,
              other.height / 2);

  Rectangle intersection(Rectangle other) =>
      Rectangle.centered(
          Point((x > other.x ? x : other.x) + other.width / 2),
          other.width / 2,
          other.height / 2);

  Rectangle subtract(Rectangle other) =>
      other.isZero() ? this : Rectangle.centered(
              Point(other.x + other.width / 2),
              other.width / 2,
              other.height / 2);

  Rectangle grow(double delta) =>
      Rectangle.centered(Point(x + delta, y + delta), width - 2 * delta,
              height - 2 * delta);

  Rectangle scale(double scale) =>
      Rectangle.centered(Point(x * scale, y * scale), width * scale,
              height * scale);

  Rectangle translate(Point delta) =>
      Rectangle.centered(Point(x + delta.x, y + delta.y), width, height);

  Rectangle translate(double dx, double dy) =>
      Rectangle.centered(Point(x + dx, y + dy), width, height);

  Rectangle translate(List<double> offsets) =>
      Rectangle.centered(
          Point(x + offsets[0], y + offsets[1]), width, height);

  Rectangle clone() => Rectangle.centered(Point(x, y), width, height);

  Rectangle copy() => Rectangle.fromRect(this);

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';
}

