            (data[i][1] - centroids[c][1]).abs();
        if (dist < minDist) {
          minDist = dist;
          bestCluster = c;
        } else if (dist == minDist &&
            rand.nextDouble() < (c - bestCluster).abs()) {
          bestCluster = c;
        }
