class KMeans {
  final Random random;
  final int k;
  final List<List<double>> data;
  final double tolerance;
  final int maxIterations;

  KMeans(this.random, this.k, this.data, this.tolerance, this.maxIterations);

  List<List<double>> _clusterPoints(List<List<double>> data, List<int> labels, int cluster) {
    final points = <List<double>>[];
    for (var i = 0; i < data.length; i++) {
      if (labels[i] == cluster) {
        points.add(List<double>.from(data[i]));
      }
    }
    return points;
  }

  List<List<double>> _centroids(List<List<double>> data, List<int> labels) {
    final numClusters = data.length;
    final centroids = <List<double>>[];
    for (var i = 0; i < numClusters; i++) {
      final points = _clusterPoints(data, labels, i);
      final sum = List<double>.filled(data[0].length, 0.0);
      for (final p in points) {
        for (var j = 0; j < data[0].length; j++) {
          sum[j] += p[j];
        }
      }
      for (var j = 0; j < data[0].length; j++) {
        sum[j] = sum[j] / points.length;
      }
      centroids.add(sum);
    }
    return centroids;
  }

  double _distance(List<double> a, List<double> b) {
    var d = 0.0;
    for (var i = 0; i < a.length; i++) {
      d += pow(a[i] - b[i], 2);
    }
    return sqrt(d);
  }

  int _centroidIndex(List<List<double>> data, List<List<double>> centroids) {
    var min = double.infinity;
    var best = -1;
    for (var i = 0; i < centroids.length; i++) {
      final d = _distance(data[0], centroids[i]);
      if (d < min) {
        min = d;
        best = i;
      }
    }
    return best;
  }

  bool _converged(List<int> labels, List<List<double>> centroids) {
    var changed = false;
    for (var i = 0; i < centroids.length; i++) {
      for (var j = 0; j < i; j++) {
        if (_distance(centroids[i], centroids[j]) < tolerance) {
          changed = true;
          break;
        }
      }
      if (changed) {
        break;
      }
    }
    return !changed;
  }

  void _assignLabels(List<List<double>> data, List<List<double>> centroids, List<int> labels) {
    for (var i = 0; i < data.length; i++) {
      var idx = _centroidIndex(data, centroids);
      labels[i] = idx;
    }
  }

  void _updateCentroids(List<List<double>> data, List<List<double>> labels, List<List<double>> centroids) {
    for (var i = 0; i < centroids.length; i++) {
      final points = _clusterPoints(data, labels, i);
      final sum = List<double>.filled(data[0].length, 0.0);
      for (final p in points) {
        for (var j = 0; j < data[0].length; j++) {
          sum[j] += p[j];
        }
      }
      for (var j = 0; j < data[0].length; j++) {
        sum[j] = sum[j] / points.length;
      }
      centroids[i] = sum;
    }
  }

  void _run(List<List<double>> data, List<List<double>> centroids) {
    final numClusters = data.length;
    final labels = List<int>.filled(data.length, -1);
    var iter = 0;
    while (iter < maxIterations && !converged(labels, centroids)) {
      iter++;
      _assignLabels(data, centroids, labels);
      _updateCentroids(data, labels, centroids);
    }
    print('Converged in $iter iteration(s).');
  }

  bool converged(List<int> labels, List<List<double>> centroids) {
    for (var i = 0; i < centroids.length; i++) {
      for (var j = 0; j < i; j++) {
        if (_distance(centroids[i], centroids[j]) < tolerance) {
          return true;
        }
      }
    }
    return false;
  }

  void printClusters(List<int> labels, List<List<double>> centroids) {
    for (var i = 0; i < labels.length; i++) {
      final idx = labels[i];
      print('Cluster $idx: {');
      for (final p in _clusterPoints(centroids, idx)) {
        print('  ${p[0]}, ${p[1]}');
      }
      print('}');
    }
  }

  void run() {
    final data = [
      [1.0, 2.0],
      [1.5, 1.5],
      [5.0, 5.0],
      [8.0, 8.0],
      [1.0, 0.5],
      [9.0, 6.0],
      [8.0, 8.0],
      [1.0, 0.5],
      [7.0, 7.0],
      [0.0, 0.0],
      [7.0, 7.0],
      [2.0, 2.5],
    ];
    final centroids = _centroids(data, data.length);
    printClusters(data.map((p) => p[0]).toSet().toList(), centroids);
    _run(data, centroids);
    printClusters(data.map((p) => p[0]).toSet().toList(), centroids);
  }

  public static void main(List<String> args) {
    final random = Random(0);
    final k = 3;
    final data = args.isEmpty ? <List<double>>[] : args.map((p) => p.split(',').map(double.parse).toList()).toList();
    final tolerance = 0.05;
    final maxIterations = 100;
    final kmeans = KMeans(random, k, data, tolerance, maxIterations);
    kmeans.run();
  }
}

