    [4.5, 3.5],
    [4, 4.5],
    [2.5, 2.5],
    [3.5, 2.5],
    [1.5, 2.5],
  ];

  const double eps = 0.5;
  const int minPts = 2;
  const int maxIterations = 100;

  final int n = points.length;
  final Random random = Random(0);



  final clusters = List<List<int>>.generate(n, (_) => []);

  final visited = List<bool>.filled(n, false);

  int clusterCount = 0;

  for (var i = 0; i < n; i++) {
    if (visited[i]) continue;

    final clusterId = clusterCount;
    final region = List<int>.filled(n, 0);
    final queue = <int>[i];
    visited[i] = true;
    region[i] = clusterId;

    while (queue.isNotEmpty) {
      final current = queue.removeLast();
      for (final neighbor in neighbors(points, current)) {
        if (!visited[neighbor]) {
          queue.add(neighbor);
          visited[neighbor] = true;
          region[neighbor] = clusterId;
        }
      }
    }

    clusters.add(region);
    clusterCount++;
  }

  print('Cluster IDs: $clusters');

  var convergence = false;
  var iterations = 0;

  while (!convergence && iterations < maxIterations) {
    convergence = true;
    iterations++;

    for (var i = 0; i < n; i++) {
      if (!visited[i]) continue;
      if (clusters[i].length < minPts) {
        clusters[i] = [i];
        convergence = false;
      } else {
        final currentCluster = clusters[i];
        for (final neighbor in neighbors(points, i)) {
          if (!currentCluster.contains(neighbor)) {

            if (clusters[neighbor].length >= minPts) {

              final otherCluster = clusters[neighbor];
              final merged = List<int>.from(currentCluster)..addAll(otherCluster);
              clusters[neighbor] = merged;
              clusters[i] = merged;
            }
          }
        }
      }
    }
  }

  print('Converged in $iterations iteration(s).');
}

List<int> neighbors(List<List<double>> points, int idx) {
  final neighbors = <int>[];
  for (var j = 0; j < points.length; j++) {
    if ((points[idx][0] - points[j][0]).abs() + (points[idx][1] - points[j][1]).abs() <= eps) {
      neighbors.add(j);
    }
  }
  return neighbors;
}

